export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "午前三時七分。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "コインランドリーの蛍光灯が一本、切れかけていた。数秒おきにぴくりと瞬く。深夜勤の誰かがうたた寝をしているみたいに。残りの蛍光灯は勤勉で、どの機械も青ざめるほど白く照らしていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "外は雨だった。雨は大きなガラス一面を伝い落ち、通りの向かいのコンビニの白い光を、ひとかたまりににじませている。すりガラス越しに、眠ろうとしない月を見ているようだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "周以寧がドアを押して入ったとき、彼はもう来ていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）木曜日。やっぱり。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "壁ぎわに並んだオレンジ色のプラスチック椅子の、二つ目。いつも二つ目だ。膝の上には印刷した原稿の束が広げてあり、手には赤ペン、キャップは口にくわえている。そばでは四号の乾燥機が暖かな黄色い灯りをともして、回っていた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "この店で、本当に服を乾かしてくれるのは四号だけだ。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "一号は飛行機の離陸みたいな音を立てる。二号は十元玉を三回入れても、出てくる服はまだ生温かく湿っていて、どこか不服そうな顔をしている。三号と五号の扉には「故障」の貼り紙があり、紙はもう史跡みたいに黄ばんでいた。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）この通りでちゃんと定時に上がれるのは、たぶん四号くらいだ。少なくとも、私よりは。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "洗濯物の袋を、三号の洗濯機の前に置く。三号は彼女の洗濯機だ。一号は水が漏れるし、二号には他人の柔軟剤の匂いが残っていて、攻撃的なほどいい香りがする。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "コインを入れ、洗剤を注ぎ、スタートを押す。水音が流れこんできて、雨の音をかき消した。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それから四つ目の椅子に座った。彼とのあいだに空席をひとつはさんで、スマホを見ているふりをする。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二人は、名前を交わしたことが一度もない。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "もう半年ほどになる。毎週木曜日、準夜勤を終えて、申し送りをして、記録を書いて、スクーターで家に帰ってシャワーを浴びる。そして眠れないと気づくと、一週間ぶんの制服を抱えてここへ来る。彼はいつもいた。いつも彼女より少しだけ早く、まるでこの店が自分の仕事場であるかのように。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼について知っていることは、すべて観察から得たものだ。職業病だった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "年は二十八前後。細いフレームの眼鏡。毎週同じグレーのカーディガンで、袖口にはペンで突いたような小さな穴がある。目の下のクマの深さは、彼女の病棟でいえば術後二日目くらい。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "原稿を直すとき、彼は小声で読みあげる。一文読んで、線を一本引いて、また読む。日本語のときもあれば、中国語のときもある。どちらにも聞こえないときもあって、そういうときは、ただ文章と口げんかをしているのだった。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）翻訳者。でなければ、ものすごく真面目な変人。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "壁に貼られた利用案内の英語の部分には、もともと「Please not put the animal inside」と書かれていた。ある木曜日を境に、その一文は赤ペンで丁寧に「Do not put pets in the machines」と直され、その下に小さな字で一行が書き足されていた。「人も入れないでください。」", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）証拠はない。でも、この店で赤ペンを持ち歩いているのは一人だけ。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "四号が、チン、と鳴った。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼はキャップを口から外し、乾燥機を開けて服を抱え出した。ちょっと触って、半秒ほど止まり、それでも全部まとめて自分の袋に押しこんだ。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "四号、どうぞ。", background: Background.Root_Act1_S0, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "私、まだ二十分以上かかりますけど。それに、そっちはまだ乾いてないですよね。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "服は、もう少し湿っていても平気です。本人たちも気にしてないので。", background: Background.Root_Act1_S0, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "先週も同じこと言ってました。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "先週も、本人たちは気にしてませんでした。", background: Background.Root_Act1_S0, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "これが二人の、いちばん長い会話だった。先月打ち立てた記録に、今夜並んだ。", background: Background.Root_Act1_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）……半年たっても、これになんて返せばいいのか分からない。", background: Background.Root_Act1_S0, portrait: Portrait.ZhouYining_Smile },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "外をスクーターが一台走り抜け、水しぶきを上げた。ヘッドライトがガラスの上をすべっていく。ひどくゆっくりした流れ星のように。", background: Background.Root_Act1_S0 },
];
